export interface EntityBase { id: string; ontology_version: string; created_at: string; created_by: string }

/** The rated organization. External identifiers are stored only when verified against the submitted domain. */
export interface Organization extends EntityBase {
  legal_name: string;
  display_name: string;
  primary_domain: string;
  aliases?: string[] | null;
  cik?: string | null;
  lei?: string | null;
  wikidata_qid?: string | null;
  github_handle?: string | null;
  industry_code?: string | null;
  stage_band?: StageBand | null;
  size_band?: SizeBand | null;
  jurisdictions?: string[] | null;
  entity_confidence?: number | null;
  identifiers_verified?: boolean | null;
  resolved_at?: string | null;
}

/** Parent, subsidiary, affiliate or acquisition links between organizations. Drives independence. */
export interface OrganizationRelation extends EntityBase {
  parent_org_id: string;
  child_org_id: string;
  relation_type: OrgRelationType;
  valid_from?: string | null;
  valid_to?: string | null;
}

/** An AI system operated by the organization. Optional in v1 (decision D6); evidence may link to the organization directly. */
export interface AISystem extends EntityBase {
  owner_org_id: string;
  name: string;
  use_case?: string | null;
  deployment_context?: string | null;
  criticality?: Criticality | null;
  valid_from?: string | null;
  valid_to?: string | null;
}

/** An assertion the organization makes about itself. A claim is never evidence of its own truth. Uploads enter as claims. */
export interface Claim extends EntityBase {
  claimant_org_id: string;
  assertion_text: string;
  scope_type: ClaimScopeType;
  scope_id?: string | null;
  claimed_at?: string | null;
  source_document_id?: string | null;
  verified_by_org_id?: string | null;
}

/** A governance mechanism protecting a system or the organization. */
export interface Control extends EntityBase {
  org_id: string;
  ai_system_id?: string | null;
  name: string;
  intended_risk?: string | null;
  owner_role?: string | null;
  threshold?: string | null;
  monitoring?: string | null;
  can_pause_or_rollback?: boolean | null;
  operational_status: ControlOperationalStatus;
  valid_from?: string | null;
  valid_to?: string | null;
}

/** A point-in-time test of a control. A failed test is kept and shown, never dropped. */
export interface TestOutcome extends EntityBase {
  control_id: string;
  protocol?: string | null;
  performed_at: string;
  result: TestResult;
  measured_value?: string | null;
  assessor_org_id?: string | null;
  verifier_org_id?: string | null;
}

/** One row per real-world event regardless of article count. News reports attach as evidence (AT-04). */
export interface Incident extends EntityBase {
  canonical_event_key: string;
  org_id: string;
  ai_system_id?: string | null;
  title: string;
  summary?: string | null;
  occurred_at?: string | null;
  severity: IncidentSeverity;
  status: IncidentStatus;
  affected_control_ids?: string[] | null;
  most_material_criterion?: CriterionCode | null;
}

/** An action taken to fix an incident. Closure counts as independently verified only with an independent verifier. */
export interface Remediation extends EntityBase {
  incident_id: string;
  action: string;
  committed_at?: string | null;
  completed_at?: string | null;
  verified_by_org_id?: string | null;
}

/** Who published a source document. org_id is set when the publisher is the rated organization or an affiliate. */
export interface Publisher extends EntityBase {
  name: string;
  domain: string;
  publisher_type: PublisherType;
  org_id?: string | null;
}

/** A configured evidence source. A new source is a configuration row, not an ontology change. */
export interface Connector extends EntityBase {
  code: string;
  name: string;
  access_terms?: string | null;
  status: ConnectorStatus;
}

/** Proof that a fetch was attempted for an assessment and how it ended (IC-16). Recorded even when nothing came back. */
export interface ConnectorRun extends EntityBase {
  assessment_id: string;
  connector_id: string;
  outcome: ConnectorRunOutcome;
  error_code?: string | null;
  items_returned: number;
  started_at: string;
  finished_at?: string | null;
  notes?: string | null;
}

/** A frozen copy of a fetched or uploaded document with its hash, dates and rights. A re-fetch with a different hash is a new row. */
export interface SourceDocument extends EntityBase {
  canonical_url: string;
  publisher_id: string;
  connector_run_id: string;
  cluster_id?: string | null;
  title?: string | null;
  content_type?: string | null;
  language?: string | null;
  published_at?: string | null;
  retrieved_at: string;
  sha256: string;
  text_sha256: string;
  snapshot_uri: string;
  text_uri: string;
  extraction_version: string;
  rights?: string | null;
  valid_from?: string | null;
  valid_to?: string | null;
  supersedes_id?: string | null;
}

/** Groups syndicated or near-duplicate documents so they count once for independence and confidence (IC-09). */
export interface SourceCluster extends EntityBase {
  cluster_key: string;
  method: ClusterMethod;
  simhash?: string | null;
}

/** The citable unit. The exact quote with character offsets into the stored text (IC-03). */
export interface EvidenceSpan extends EntityBase {
  source_document_id: string;
  char_start: number;
  char_end: number;
  quote: string;
  extracted_assertion?: string | null;
  asserted_dates?: string[] | null;
  section_heading?: string | null;
  supersedes_id?: string | null;
}

/** The only bridge from evidence to a score. One span, one target, one criterion, six separate judgments (spec section 6). */
export interface EvidenceLink extends EntityBase {
  span_id: string;
  target_type: TargetType;
  target_id: string;
  criterion_code: CriterionCode;
  polarity: Polarity;
  admissibility: Admissibility;
  admissibility_reason?: string | null;
  maturity_rung: MaturityRung;
  execution_level: ExecutionLevel;
  evidence_class: EvidenceClass;
  independence: Independence;
  source_tier: SourceTier;
  proposer: string;
  relevance?: number | null;
  valid_from?: string | null;
  valid_to?: string | null;
  reviewer_id?: string | null;
  supersedes_id?: string | null;
}

/** A released methodology. Only a signed Humaital change record creates a new version. */
export interface MethodologyVersion extends EntityBase {
  semver: string;
  effective_from?: string | null;
  approved_by?: string | null;
  change_record_uri?: string | null;
  status: MethodologyStatus;
  manifest_hash: string;
}

/** One of the six pillars. */
export interface Pillar extends EntityBase {
  methodology_version_id: string;
  code: PillarCode;
  name: string;
  display_order: number;
  weight: number;
}

/** One of the twenty criteria. Codes are permanent; retired codes are never reused. */
export interface Criterion extends EntityBase {
  methodology_version_id: string;
  pillar_id: string;
  code: CriterionCode;
  pillar_code: PillarCode;
  name: string;
  definition: string;
  legacy_id?: string | null;
  content_status: ContentStatus;
  materiality: Materiality;
  materiality_weight: number;
  weight: number;
  freshness_window_months: number;
}

/** What each level 1 to 5 means for one criterion, and the maturity rung it requires (decision D1). */
export interface LevelDescriptor extends EntityBase {
  criterion_id: string;
  level: number;
  descriptor: string;
  required_maturity_rung: MaturityRung;
}

/** When a criterion does not apply or must be reviewed (decision D5). */
export interface CriterionApplicability extends EntityBase {
  criterion_id: string;
  condition: string;
  effect: ApplicabilityEffect;
}

/** One rule of a ruleset, referenced by code so traces can name it. */
export interface Rule extends EntityBase {
  ruleset_version: string;
  code: string;
  kind: RuleKind;
  scope: RuleScope;
  run_order: number;
  expression_ref: string;
  parameters?: unknown | null;
  description?: string | null;
}

/** One scoring run. Pins every version (IC-18). lifecycle_state follows spec section 8.1. */
export interface Assessment extends EntityBase {
  org_id: string;
  parent_assessment_id?: string | null;
  requested_by: string;
  submitted_domain: string;
  direct_urls?: string[] | null;
  stage_band: StageBand;
  size_band: SizeBand;
  methodology_version: string;
  ruleset_version: string;
  prompt_version: string;
  model_id: string;
  lifecycle_state: LifecycleState;
  idempotency_key?: string | null;
  certification_requested: boolean;
  failure_reason?: string | null;
  started_at?: string | null;
  finished_at?: string | null;
}

/** Frozen copy of every link's judgment columns, incident states and version pins. The rules engine reads only this (AT-07). */
export interface EvidenceSnapshot extends EntityBase {
  assessment_id: string;
  frozen_at: string;
  manifest_hash: string;
  span_ids: string[];
  link_ids: string[];
  link_states: unknown;
  incident_states: unknown;
  connector_runs: unknown;
  version_pins: unknown;
  snapshot_sha256: string;
}

/** LLM or heuristic output. Advisory only. Rejected findings are stored for audit and never used (IC-05). */
export interface CriterionFinding extends EntityBase {
  assessment_id: string;
  criterion_code: CriterionCode;
  proposed_level: number;
  evidence_link_ids: string[];
  contradicting_link_ids?: string[] | null;
  uncertainty: number;
  reasoning_summary: string;
  provider: string;
  model_id: string;
  prompt_version: string;
  attempt: number;
  validation_status: FindingValidationStatus;
  validation_errors?: unknown | null;
  raw_output?: unknown | null;
  role: string;
}

/** Rules-engine output. The only source of criterion levels. Every decision lists the rules that ran (IC-14). */
export interface CriterionDecision extends EntityBase {
  assessment_id: string;
  criterion_code: CriterionCode;
  level?: number | null;
  coverage_state: CoverageState;
  confidence: number;
  applied_rule_codes: string[];
  finding_id?: string | null;
  trace: unknown;
  review_required: boolean;
  supersedes_id?: string | null;
}

/** Derived per pillar; never edited. */
export interface PillarScore extends EntityBase {
  assessment_id: string;
  pillar_code: PillarCode;
  score: number;
  confidence: number;
  criteria_counted: number;
  criteria_excluded: number;
  supersedes_id?: string | null;
}

/** The HAI Score, confidence and effectiveness plus the outcome status set only by the rules engine (AT-10). */
export interface AssessmentResult extends EntityBase {
  assessment_id: string;
  hai_score?: number | null;
  confidence_pct?: number | null;
  effectiveness?: number | null;
  score_before_caps?: number | null;
  caps_applied?: string[] | null;
  outcome_status: OutcomeStatus;
  gate_reasons?: string[] | null;
  review_triggers?: string[] | null;
  ruleset_version: string;
  result_sha256: string;
  supersedes_id?: string | null;
}

/** Signed by a named reviewer. Never written by the LLM, the engine or the browser (IC-13). */
export interface CertificationDecision extends EntityBase {
  assessment_id: string;
  result_id: string;
  threshold_applied: number;
  decision: CertificationOutcome;
  gate_reasons?: string[] | null;
  reviewer_id: string;
  signed_at: string;
  expires_at?: string | null;
  certificate_number?: string | null;
  signature: string;
  supersedes_id?: string | null;
}

/** A human decision on an incident, contradiction, borderline confidence, finding, link, appeal or certification. Always with a reason. */
export interface Review extends EntityBase {
  subject_type: ReviewSubjectType;
  subject_id: string;
  assessment_id?: string | null;
  reviewer_id: string;
  action: ReviewAction;
  reason: string;
  decided_at: string;
}

/** Append-only, hash-chained record of every decision-bearing write (AT-15). */
export interface AuditEvent extends EntityBase {
  seq: number;
  actor: string;
  action: string;
  subject_type: string;
  subject_id?: string | null;
  before?: unknown | null;
  after?: unknown | null;
  reason?: string | null;
  at: string;
  prev_hash: string;
  hash: string;
}

